24	// postDocChanges posts one batch of changes with ids c1..cN and payloads
25	// {"n":i} from the given device.
26	func postDocChanges(t *testing.T, h http.Handler, doc, device string, n int) {
27		t.Helper()
28		batch := make([]any, n)
