	if err != nil {
		return 0, 0, err
	}
	if err := tx.Commit(); err != nil {
		return 0, 0, err
	}
	// Compaction is not a change: no waiter is woken and no subscriber is
	// signaled, because no new change exists to observe.
	return boundary, removed, nil
}

// CompactChangesAuthorized is the session-scoped compaction: it has exactly
// the trimming semantics of CompactChanges, but the device identity was
// resolved from the session by the HTTP layer before the call. The gate
// (registration then permission) is still enforced first in the same
// serialized transaction: an unregistered device yields
// store.ErrDeviceNotFound and a revoked device yields ErrPermissionDenied, and
// neither touches any state or observes change content. It shares the compact
// transaction core with the document-level entry so the two paths cannot
// drift.
func (s *Service) CompactChangesAuthorized(documentID, deviceID string) (boundary, removed int64, err error) {
	tx, err := s.db.Begin()
	if err != nil {
		return 0, 0, err
	}
	defer func() { _ = tx.Rollback() }()

	// Gate first: the device row and the permission row are read before any
	// snapshot cursor or change content is observed, so a rejected compaction
	// cannot reveal anything.
	if s.gate != nil {
		if err := s.gate.DeviceAuthorizedTx(tx, documentID, deviceID); err != nil {
			return 0, 0, err
		}
	}

	boundary, removed, err = compactChangesTx(tx, documentID)
	if err != nil {
		return 0, 0, err
	}
	if err := tx.Commit(); err != nil {
		return 0, 0, err
	}
	return boundary, removed, nil
}

// compactChangesTx moves every change of documentID whose cursor is at or
// below the compaction boundary out of the online log, inside the caller's
// serialized transaction, and returns the reported boundary together with the
// number of changes this call removed. It is shared by the document-level and
// session-scoped entries.
//
// The boundary is the greatest cursor with a saved snapshot, or zero when the
// documentID has no snapshot — compacting a snapshot-less or unknown document
// succeeds and removes nothing. A repeat (the stored boundary already reaches
// the snapshot boundary) reports the standing boundary and removes nothing.
func compactChangesTx(tx *sql.Tx, documentID string) (boundary, removed int64, err error) {
	// The boundary is the greatest cursor with a saved snapshot, 0 when the
	// document has none (an unknown document included).
	if err := tx.QueryRow(
		`SELECT COALESCE(MAX(cursor), 0) FROM snapshots WHERE document_id = ?`,
		documentID,
	).Scan(&boundary); err != nil {
		return 0, 0, err
	}
	stored, err := boundaryOfTx(tx, documentID)
	if err != nil {
		return 0, 0, err
	}
	if boundary <= stored {
		// Nothing new to trim (a repeat compaction, or a snapshot-less
		// document): report the standing boundary and remove nothing.
		return stored, 0, nil
	}

